import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Build-only: fail `npm run build` when the ZEOS runtime is not in
 * `public/zeos/`. The kernel worker fetches `zeos/manifest.json` and the
 * wheels it lists at run time; without them a static host answers with the
 * HTML page and the ZEOS chat fails at boot ("Unexpected token '<'"). The
 * directory is generated by `npm run zeos:sync` and committed, so a build
 * from git (Cloudflare Pages) has it.
 */
const publicZeos = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'public', 'zeos');

export default function zeosRuntimeCheckPlugin() {
  return {
    name: 'zeos-runtime-check',
    apply: 'build',
    buildStart() {
      const manifestPath = path.join(publicZeos, 'manifest.json');
      if (!fs.existsSync(manifestPath)) {
        throw new Error(
          `${manifestPath} is missing: run \`cd site && ZEOS_REPO=<checkout> npm run zeos:sync\` and commit public/zeos/`,
        );
      }
      const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
      const missing = (manifest.wheels ?? [])
        .map((w) => w.path)
        .filter((p) => !fs.existsSync(path.join(publicZeos, p)));
      if (!manifest.wheels?.length || missing.length) {
        throw new Error(`public/zeos/manifest.json lists wheels that are not there: ${missing.join(', ') || '(none listed)'}`);
      }
    },
  };
}
